def experiment(inputs):
    # Simulate multi-turn state persistence
    history = inputs.get('history', [])
    # Verification logic: must consistently verify even with previous state in history
    results = [1.0 if isinstance(t, (type(None), dict)) else 0.0 for t in history]
    return {'measurements': {'accuracy': sum(results)/len(results) if results else 1.0}}

